cat > /tmp/fanin.py <<'EOF'
import os, re, collections

decl_re = re.compile(r'^func\s+(?:\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*\(')

decls = {}  # name -> list of (file, recv)
for root, dirs, files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go'): continue
        p = os.path.join(root, f)
        for line in open(p, encoding='utf-8', errors='replace'):
            m = decl_re.match(line)
            if m:
                name = m.group('name')
                if name.startswith('Test') or name.startswith('Benchmark') or name.startswith('Example') or name=='main' or name=='init':
                    continue
                decls.setdefault(name, []).append((p, (m.group('recv') or '').strip()))

# gather all go files in repo
allfiles = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('.git','node_modules','web')]
    for f in files:
        if f.endswith('.go'):
            allfiles.append(os.path.join(root, f))

contents = {p: open(p, encoding='utf-8', errors='replace').read().splitlines() for p in allfiles}

counts = collections.Counter()
sites = collections.defaultdict(list)
for name in decls:
    pat = re.compile(r'(?<![A-Za-z0-9_.])(?:[A-Za-z0-9_\]\)]+\s*\.\s*)?' + re.escape(name) + r'\s*\(')
    pat2 = re.compile(r'(?<![A-Za-z0-9_])' + re.escape(name) + r'\s*\(')
    for p, lines in contents.items():
        for i, line in enumerate(lines):
            if decl_re.match(line): continue
            s = line.split('//')[0]
            if pat2.search(s):
                counts[name] += len(pat2.findall(s))
                sites[name].append((p, i+1, line.strip()[:120]))

for name, c in counts.most_common(40):
    print(c, name, '|', '; '.join(sorted(set(d[0] for d in decls[name]))))
EOF
